def parse_min_should_match(num_clauses: int, spec: str) -> int:
    """
    This function parses the "min should match" specification (commonly referred to as 'mm' spec) 
    from Solr's search engine configuration and calculates the minimum number of clauses that must match 
    based on the given specification and the total number of clauses. It supports both absolute and 
    percentage-based specifications, as well as conditional specifications using '<'.

    Input-Output Arguments
    :param num_clauses: int, the total number of clauses in the query.
    :param spec: str, the 'min should match' specification as a string, which can include absolute numbers, 
                 percentages, and conditional expressions.
    :return: int, the calculated minimum number of clauses that must match according to the 'mm' spec.
    """

    # Check if the spec is an absolute number
    if spec.isdigit():
        # If it's an absolute number, return the number
        return int(spec)

    # Check if the spec is a percentage
    if spec.endswith('%'):
        # If it's a percentage, calculate the number of clauses that must match
        percentage = float(spec[:-1])
        return int((percentage / 100) * num_clauses)

    # Check if the spec is a conditional expression
    if '<' in spec:
        # If it's a conditional expression, split the spec into two parts
        parts = spec.split('<')
        # The first part is the number of clauses that must match if the condition is true
        must_match = parts[0]
        # The second part is the condition
        condition = parts[1]
        # Check if the condition is an absolute number
        if condition.isdigit():
            # If the condition is an absolute number, check if the number of clauses is less than the condition
            if num_clauses < int(condition):
                # If the number of clauses is less than the condition, return the number of clauses
                return num_clauses
            else:
                # If the number of clauses is not less than the condition, return the number of clauses that must match
                if must_match.isdigit():
                    return int(must_match)
                elif must_match.endswith('%'):
                    percentage = float(must_match[:-1])
                    return int((percentage / 100) * num_clauses)
        # Check if the condition is a percentage
        elif condition.endswith('%'):
            # If the condition is a percentage, calculate the number of clauses that must match if the condition is true
            percentage = float(condition[:-1])
            condition_num_clauses = int((percentage / 100) * num_clauses)
            # Check if the number of clauses is less than the condition
            if num_clauses < condition_num_clauses:
                # If the number of clauses is less than the condition, return the number of clauses
                return num_clauses
            else:
                # If the number of clauses is not less than the condition, return the number of clauses that must match
                if must_match.isdigit():
                    return int(must_match)
                elif must_match.endswith('%'):
                    percentage = float(must_match[:-1])
                    return int((percentage / 100) * num_clauses)

    # If the spec is not an absolute number, percentage, or conditional expression, raise a ValueError
    raise ValueError("Invalid 'min should match' specification")
